    # Generalize to substrings if applicable
    if len(s_in) >= 2 and len(s_out) >= 2:
        # Try 2-character patterns
        if len(s_in) >= 2 and len(s_out) >= 2:
            candidates.append((s_in[0:2], s_out[0:2]))

