def find_changed_pairs(inputs, outputs):
    changed = []
    for i, (inp, out) in enumerate(zip(inputs, outputs)):
        if inp != out:
            changed.append((i, inp, out))
    return changed

def find_minimal_edit(s_in, s_out):
    # Find first difference
    for i, (c_in, c_out) in enumerate(zip(s_in, s_out)):
        if c_in != c_out:
            return (c_in, c_out, i)

    # Handle length differences
    if len(s_in) != len(s_out):
        if len(s_in) > len(s_out):
            return (s_in[len(s_out)], '', len(s_out))
        else:
            return ('', s_out[len(s_in)], len(s_in))

    return ('', '', -1)

def propose_rule_candidates(s_in, s_out):
    # Return most specific candidates first
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)
    candidates = []

    if old_sub and new_sub:
        candidates.append((old_sub, new_sub))  # Most specific

    # Add some generalizations if possible
    if len(s_in) >= 2 and len(s_out) >= 2:
        candidates.append((s_in[0:2], s_out[0:2]))  # 2-char pattern

    return candidates

# Apply to our data
inputs = ['dzzw', 'dj', 'jidzu', 'ajki', 'ijxihz']
outputs = ['dzzw', 'dg', 'gidzwf', 'bgki', 'igxibaz']

changed = find_changed_pairs(inputs, outputs)
print("Changed pairs:", changed)

# Start building rules from the first change
rules = []

# Process each changed pair
for idx, s_in, s_out in changed:
    print(f"\nProcessing pair {idx}: '{s_in}' -> '{s_out}'")

    # Get candidates
    candidates = propose_rule_candidates(s_in, s_out)
    print(f"Candidates: {candidates}")

    # Try the first (most specific) candidate
    if candidates:
        pattern, replacement = candidates[0]
        print(f"Trying rule: replace('{pattern}', '{replacement}')")

        # Test if this rule would work properly by applying it to all inputs
        test_results = []
        for i, inp in enumerate(inputs):
            result = inp.replace(pattern, replacement)
            test_results.append(result)

        print(f"Test results: {test_results}")

        # Check if this creates conflicts with other pairs
        all_correct = True
        for i, (inp, out) in enumerate(zip(inputs, outputs)):
            if inp != out:
                if test_results[i] != out:
                    all_correct = False
                    break

        print(f"All correct with this rule: {all_correct}")

        if all_correct:
            rules.append((pattern, replacement))
            print(f"Added rule: {pattern} -> {replacement}")
        else:
            print("Rule causes conflicts, skipping")

print(f"\nFinal rules: {rules}")

